package com.finsightai.service;
import com.finsightai.model.Transaction; import com.finsightai.repository.TransactionRepository; import org.springframework.data.jpa.domain.Specification; import org.springframework.stereotype.Service; import java.time.LocalDate; import java.util.*;
@Service public class TransactionService {private final TransactionRepository repo; private final AuditService audit; public TransactionService(TransactionRepository r,AuditService a){repo=r;audit=a;} public List<Transaction> search(String q,String type,String category,LocalDate from,LocalDate to){Specification<Transaction>s=Specification.where(null);if(q!=null&&!q.isBlank())s=s.and((r,x,c)->c.or(c.like(c.lower(r.get("description")),"%"+q.toLowerCase()+"%"),c.like(c.lower(r.get("account")),"%"+q.toLowerCase()+"%")));if(type!=null&&!type.isBlank())s=s.and((r,x,c)->c.equal(c.upper(r.get("type")),type.toUpperCase()));if(category!=null&&!category.isBlank())s=s.and((r,x,c)->c.equal(c.lower(r.get("category")),category.toLowerCase()));if(from!=null)s=s.and((r,x,c)->c.greaterThanOrEqualTo(r.get("transactionDate"),from));if(to!=null)s=s.and((r,x,c)->c.lessThanOrEqualTo(r.get("transactionDate"),to));return repo.findAll(s);}public Transaction create(Transaction t){t.setId(null);Transaction saved=repo.save(t);audit.record("CREATE","TRANSACTION",saved.getId().toString(),"Created transaction "+saved.getDescription());return saved;}public Transaction update(Long id,Transaction in){Transaction t=repo.findById(id).orElseThrow();t.setTransactionDate(in.getTransactionDate());t.setAccount(in.getAccount());t.setCategory(in.getCategory());t.setType(in.getType());t.setAmount(in.getAmount());t.setDepartment(in.getDepartment());t.setDescription(in.getDescription());t.setSourceSystem(in.getSourceSystem());Transaction saved=repo.save(t);audit.record("UPDATE","TRANSACTION",id.toString(),"Updated transaction");return saved;}public void delete(Long id){repo.deleteById(id);audit.record("DELETE","TRANSACTION",id.toString(),"Deleted transaction");}}
